critique.content:
{
  "requires_refine": true,
  "issues": [
    {
      "category": "consistency",
      "description": "The translation uses 'system calls' and 'interrupt handler' instead of the required Spanish terms 'llamada al sistema' and 'interrupt handler' (the latter is allowed, but the former should be translated per instructions)."
    },
    {
      "category": "consistency",
      "description": "The translation uses 'realiza el wakeup' instead of the required term 'wakeup' (as a concept) or 'despierta' (though the instructions suggest keeping 'wakeup' as an English term, the phrasing 'realiza el wakeup' is a clunky calque)."
    },
    {
      "category": "fluency",
      "description": "The phrase 'en el hilo del kernel de un proceso' is slightly awkward; 'en el hilo del kernel de un proceso' is acceptable but 'en un hilo del kernel de un proceso' would be more natural."
    }
  ]
}

